"""Images that belong to a conversation: generated by image tools or uploaded.

Bytes live in object storage under ``storage_key``; this row records where an
image came from (the durable tool operation, or later a user upload) and the
image it was edited from, if any.
"""

import uuid

from sqlalchemy import BigInteger, CheckConstraint, ForeignKeyConstraint, Integer, Text
from sqlalchemy import UniqueConstraint
from sqlalchemy.dialects.postgresql import UUID
from sqlalchemy.orm import Mapped, mapped_column

from src.models.base import OrgScopedModel

# Register the referenced interaction tables for isolated metadata imports.
from src.models import interaction  # noqa: F401

IMAGE_CONTENT_TYPES = ("image/png", "image/jpeg", "image/webp")


class ConversationImage(OrgScopedModel):
    __tablename__ = "conversation_images"
    __table_args__ = (
        UniqueConstraint("org_id", "id", name="uq_conversation_image_org_id"),
        UniqueConstraint("storage_key", name="uq_conversation_image_storage_key"),
        UniqueConstraint("org_id", "operation_id", name="uq_conversation_image_operation"),
        ForeignKeyConstraint(
            ["org_id", "conversation_id"],
            ["conversation_identities.org_id", "conversation_identities.id"],
            name="fk_conversation_image_conversation",
            ondelete="CASCADE",
        ),
        ForeignKeyConstraint(
            ["org_id", "turn_id", "execution_id", "operation_id"],
            [
                "tool_operations.org_id",
                "tool_operations.turn_id",
                "tool_operations.execution_id",
                "tool_operations.id",
            ],
            name="fk_conversation_image_operation",
            ondelete="CASCADE",
        ),
        CheckConstraint("origin IN ('generated','uploaded')", name="ck_conversation_image_origin"),
        CheckConstraint(
            "content_type IN ('image/png','image/jpeg','image/webp')",
            name="ck_conversation_image_content_type",
        ),
        CheckConstraint("size_bytes > 0", name="ck_conversation_image_size"),
    )

    conversation_id: Mapped[uuid.UUID] = mapped_column(UUID(as_uuid=True), nullable=False)
    turn_id: Mapped[uuid.UUID | None] = mapped_column(UUID(as_uuid=True))
    execution_id: Mapped[uuid.UUID | None] = mapped_column(UUID(as_uuid=True))
    operation_id: Mapped[uuid.UUID | None] = mapped_column(UUID(as_uuid=True))
    origin: Mapped[str] = mapped_column(Text, nullable=False)
    source_image_id: Mapped[uuid.UUID | None] = mapped_column(UUID(as_uuid=True))
    storage_key: Mapped[str] = mapped_column(Text, nullable=False)
    content_type: Mapped[str] = mapped_column(Text, nullable=False)
    size_bytes: Mapped[int] = mapped_column(BigInteger, nullable=False)
    width: Mapped[int | None] = mapped_column(Integer)
    height: Mapped[int | None] = mapped_column(Integer)
    prompt: Mapped[str | None] = mapped_column(Text)
    model: Mapped[str | None] = mapped_column(Text)
